let container = document.querySelector(".card-container");

// create card
// div(card)--> img(img) --> div(blur) -> div(content)[h2, p
// (card-text)]
function showUser() {
  users.forEach((element) => {
    console.log(element);

    let card = document.createElement("div");
    card.classList.add("card");

    let img = document.createElement("img");
    img.classList.add("img");
    img.setAttribute("src", element.pic);
    let div_blur = document.createElement("div");
    div_blur.classList.add("blur");

    let content = document.createElement("div");
    content.classList.add("content");

    let h2 = document.createElement("h2");
    h2.textContent = element.name;
    let p = document.createElement("p");
    p.classList.add("card-text");
    p.textContent = element.bio;

    // appendChild
    container.appendChild(card);
    card.appendChild(img);
    card.appendChild(div_blur);
    card.appendChild(content);
    content.appendChild(h2);
    content.appendChild(p);

    console.log(container);
  });
}
showUser();

let inpBox = document.querySelector(".bar");
inpBox.addEventListener("input", () => {
  //filter
  let filter = inpBox.value.toUpperCase();
  let card = document.querySelectorAll(".card");
  for (let i = 0; i < card.length; i++) {
    let txtValue = card[i].textContent || card[i].innerText;
    if (txtValue.toUpperCase().indexOf(filter) > -1) {
      card[i].style.display = "";
    } else {
      card[i].style.display = "none";
    }
  }
});
